# E2E verification tests for OpenCode replacement (Spec #5)
# Verifies AC-1 through AC-12 from the spec
# Generated by @fredo-tester

param(
  [string]$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..'))
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$script:passed = 0
$script:failed = 0
$script:results = @()

function Assert-True {
  param([bool]$Condition, [string]$Message, [string]$AC = '', [string]$Evidence = '')
  if ($Condition) {
    $script:passed++
    $script:results += @{ AC = $AC; Status = 'PASS'; Message = $Message; Evidence = $Evidence }
    Write-Host "  PASS: $Message" -ForegroundColor Green
  } else {
    $script:failed++
    $script:results += @{ AC = $AC; Status = 'FAIL'; Message = $Message; Evidence = $Evidence }
    Write-Host "  FAIL: $Message" -ForegroundColor Red
  }
}

function Search-InFiles {
  param(
    [string]$Pattern,
    [string[]]$Extensions,
    [string]$Directory,
    [string[]]$ExcludeDirs = @()
  )
  $hits = @()
  $files = Get-ChildItem -LiteralPath $Directory -Recurse -File -ErrorAction SilentlyContinue
  foreach ($f in $files) {
    $ext = $f.Extension.ToLower()
    if ($Extensions -notcontains $ext) { continue }
    $excluded = $false
    foreach ($ex in $ExcludeDirs) {
      if ($f.FullName -like "*$ex*") { $excluded = $true; break }
    }
    if ($excluded) { continue }
    $content = Get-Content $f.FullName -Raw -ErrorAction SilentlyContinue
    if (-not $content) { continue }
    $matches = [regex]::Matches($content, $Pattern, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($matches.Count -gt 0) {
      $hits += @{ File = $f.FullName; Count = $matches.Count; Lines = @() }
      foreach ($m in $matches) {
        $lineNum = (Get-Content $f.FullName | Select-String -Pattern $Pattern -SimpleMatch:$false | Select-Object -First 3).LineNumber
      }
    }
  }
  return $hits
}

$rustSrcDir = Join-Path $RepoRoot 'apps\tauri\src-tauri\src'
$uiSrcDir = Join-Path $RepoRoot 'apps\ui\src'
$docsDir = Join-Path $RepoRoot 'docs'
