$tsHitDetail = if ($tsHitCount -gt 0) { ($tsHits | ForEach-Object { $_.File }) -join '; ' } else { 'none' }
Assert-True -Condition ($tsHitCount -eq 0) -Message "UI source has no copilot/claude references (found $tsHitCount files: $tsHitDetail)" -AC 'AC-1' -Evidence $tsHitDetail

# Check JSON config files (not tokenizer model files)
$jsonHits = Search-InFiles -Pattern '\bcopilot\b|\bclaude\b' -Extensions @('.json') -Directory (Join-Path $RepoRoot 'apps') -ExcludeDirs @('models', 'node_modules', 'dist', 'target')
$jsonHitCount = ($jsonHits | Measure-Object).Count
$jsonHitDetail = if ($jsonHitCount -gt 0) { ($jsonHits | ForEach-Object { $_.File }) -join '; ' } else { 'none' }
Assert-True -Condition ($jsonHitCount -eq 0) -Message "App JSON files have no copilot/claude references (found $jsonHitCount files: $jsonHitDetail)" -AC 'AC-1' -Evidence $jsonHitDetail

