# ── AC-8: EventSource enum casing consistency ──────────────────────────────

Write-Host ""
Write-Host "--- AC-8: EventSource enum casing consistency ---" -ForegroundColor Yellow

$eventSourceCheckFiles = @(
  @{ Name = 'DevMode.tsx'; Path = (Join-Path $uiSrcDir 'features\dev-mode\components\DevMode.tsx') },
  @{ Name = 'useDevModeStream.ts'; Path = (Join-Path $uiSrcDir 'features\dev-mode\hooks\useDevModeStream.ts') },
  @{ Name = 'SpatiotemporalManifold.tsx'; Path = (Join-Path $uiSrcDir 'features\dev-mode\components\SpatiotemporalManifold.tsx') }
)

# The correct EventSource values (matching Rust serde camelCase) are:
# 'hook', 'otlpGrpc', 'otlpHttp'
# Wrong PascalCase values that would break at runtime:
# 'Hook', 'OtlpGrpc', 'OtlpHttp'

foreach ($fileInfo in $eventSourceCheckFiles) {
  if (Test-Path $fileInfo.Path) {
    $content = Get-Content $fileInfo.Path -Raw

    # Check for PascalCase EventSource string literals
    $hasHookPascal = $content -match "'Hook'"
    $hasOtlpGrpcPascal = $content -match "'OtlpGrpc'"
    $hasOtlpHttpPascal = $content -match "'OtlpHttp'"

    $wrongCount = 0
    if ($hasHookPascal) { $wrongCount++ }
    if ($hasOtlpGrpcPascal) { $wrongCount++ }
    if ($hasOtlpHttpPascal) { $wrongCount++ }

    if ($wrongCount -gt 0) {
      Assert-True -Condition $false -Message "$($fileInfo.Name) uses PascalCase EventSource values ($wrongCount instances - should be camelCase: 'hook', 'otlpGrpc', 'otlpHttp')" -AC 'AC-8' -Evidence "PascalCase EventSource references break type safety"
    } else {
      Assert-True -Condition $true -Message "$($fileInfo.Name) uses correct camelCase EventSource values" -AC 'AC-8'
    }
  } else {
    Assert-True -Condition $false -Message "$($fileInfo.Name) not found" -AC 'AC-8'
  }
}

